date -Is; echo "clock_mode=MAXN-dvfs (not pinned; shared machine)"; echo "$ nvpmodel -q"; nvpmodel -q 2>&1; echo "$ jetson_clocks --show"; jetson_clocks --show 2>&1 | head -5; for d in /sys/class/devfreq/*; do echo "$d gov=$(cat $d/governor 2>/dev/null) cur=$(cat $d/cur_freq 2>/dev/null) min=$(cat $d/min_freq 2>/dev/null) max=$(cat $d/max_freq 2>/dev/null)"; done; for p in /sys/devices/system/cpu/cpufreq/policy*; do echo "$p $(cat $p/scaling_governor) cur=$(cat $p/scaling_cur_freq) min=$(cat $p/scaling_min_freq) max=$(cat $p/scaling_max_freq)"; done; echo "PVA clock: not readable without root"; uptime; echo "--- top cpu"; ps -eo pid,user,%cpu,comm --sort=-%cpu | head -8; echo "--- gpu procs"; (nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv 2>/dev/null || echo n/a)
